import { getTranslations } from "next-intl/server";
import { prisma } from "@/lib/db";
import { listProducts } from "@/lib/catalog";
import { ProductCard } from "@/components/ProductCard";
import { Breadcrumbs } from "@/components/Breadcrumbs";
import { tJson } from "@/lib/utils";
import { CatalogControls } from "@/components/CatalogControls";
import { Link } from "@/i18n/routing";
import { ArrowRight } from "lucide-react";

export default async function CatalogPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string; slug?: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const { locale, slug } = await params;
  const sp = await searchParams;
  const t = await getTranslations({ locale, namespace: "catalog" });
  const n = await getTranslations({ locale, namespace: "nav" });

  const category = slug
    ? await prisma.category.findUnique({ where: { slug } })
    : null;

  const page = Number(sp.page || 1);
  const data = await listProducts({
    category: slug,
    q: String(sp.q || ""),
    sort: String(sp.sort || "popular"),
    min: sp.min ? Number(sp.min) : undefined,
    max: sp.max ? Number(sp.max) : undefined,
    lens: String(sp.lens || ""),
    antiFog: String(sp.af || ""),
    photo: String(sp.photo || ""),
    polar: String(sp.polar || ""),
    rx: String(sp.rx || ""),
    interchangeable: String(sp.il || ""),
    brand: String(sp.brand || ""),
    page,
    locale,
  });

  const brands = await prisma.brand.findMany();
  const title = category ? tJson(category.name, locale) : t("title");

  return (
    <div className="pb-16">
      <section className="border-b border-black/10 bg-white">
        <div className="container-f py-10">
          <Breadcrumbs
            items={[
              { href: "/", label: "FORTIS" },
              { href: "/catalog", label: n("catalog") },
              ...(category ? [{ label: title }] : []),
            ]}
          />
          <div className="flex flex-wrap items-end justify-between gap-4">
            <div>
              <p className="text-xs uppercase tracking-[0.24em] text-graphite/45">FORTIS catalog</p>
              <h1 className="mt-2 font-display text-4xl">{title}</h1>
              <p className="mt-2 text-sm text-graphite/60">
                {t("found")}: {data.total}
              </p>
            </div>
            <Link href="/guide" className="inline-flex h-11 items-center gap-2 rounded-full bg-ink px-5 text-sm font-semibold text-white">
              {n("guide")} <ArrowRight size={16} />
            </Link>
          </div>
          {category?.seoText && <p className="mt-5 max-w-3xl text-sm leading-6 text-graphite/70">{tJson(category.seoText, locale)}</p>}
        </div>
      </section>

      <div className="container-f">
      <div className="mt-8 grid gap-8 lg:grid-cols-[300px_1fr]">
        <CatalogControls brands={brands} />
        <div>
          {data.items.length === 0 ? (
            <div className="rounded-lg border border-black/10 bg-white p-10 text-center shadow-card">
              <p>{t("empty")}</p>
              <Link href="/catalog" className="mt-4 inline-block text-sm underline">
                {t("reset")}
              </Link>
            </div>
          ) : (
            <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
              {data.items.map((p) => (
                <ProductCard key={p.id} p={p} locale={locale} />
              ))}
            </div>
          )}
          {data.pages > 1 && (
            <div className="mt-8 flex gap-2">
              {Array.from({ length: data.pages }, (_, i) => (
                <Link
                  key={i}
                  href={`?page=${i + 1}`}
                  className={`grid h-10 w-10 place-items-center rounded-full border border-black/10 ${page === i + 1 ? "bg-ink text-white" : "bg-white"}`}
                >
                  {i + 1}
                </Link>
              ))}
            </div>
          )}
        </div>
      </div>
      </div>
    </div>
  );
}
